CREATE SCHEMA IF NOT EXISTS core; CREATE SCHEMA IF NOT EXISTS mart; CREATE SCHEMA IF NOT EXISTS audit;
SET search_path TO core,public;
CREATE TABLE students(student_id INT PRIMARY KEY,first_name TEXT NOT NULL,last_name TEXT NOT NULL,email TEXT UNIQUE NOT NULL,city TEXT,state TEXT,signup_date DATE NOT NULL,education_level TEXT,lead_source TEXT);
CREATE TABLE core.leads (lead_id INT PRIMARY KEY,lead_date DATE, source TEXT, campaign TEXT, lead_status TEXT,
    student_id INT REFERENCES core.students(student_id));
CREATE TABLE courses(course_id INT PRIMARY KEY,course_name TEXT NOT NULL,category TEXT,list_price NUMERIC(12,2) CHECK(list_price>=0),duration_weeks INT CHECK(duration_weeks>0));
CREATE TABLE instructors(instructor_id INT PRIMARY KEY,instructor_name TEXT NOT NULL,experience_years INT,specialization TEXT);
CREATE TABLE mentors(mentor_id INT PRIMARY KEY,mentor_name TEXT,specialization TEXT);
CREATE TABLE batches(batch_id INT PRIMARY KEY,course_id INT REFERENCES courses,batch_name TEXT,start_date DATE,end_date DATE,capacity INT CHECK(capacity>0),instructor_id INT REFERENCES instructors,CHECK(end_date>=start_date));
CREATE TABLE enrollments(enrollment_id INT PRIMARY KEY,student_id INT REFERENCES students,course_id INT REFERENCES courses,batch_id INT REFERENCES batches,enrollment_date DATE,enrollment_status TEXT CHECK(enrollment_status IN('Active','Completed','Dropped','Deferred')),discount_pct NUMERIC(5,2) CHECK(discount_pct BETWEEN 0 AND 100));
CREATE TABLE modules(module_id INT PRIMARY KEY,course_id INT REFERENCES courses,module_name TEXT,sequence_no INT,difficulty TEXT);
CREATE TABLE payments(payment_id INT PRIMARY KEY,enrollment_id INT REFERENCES enrollments,payment_date DATE,amount NUMERIC(12,2) CHECK(amount>=0),payment_method TEXT,payment_status TEXT CHECK(payment_status IN('Success','Failed','Refunded')),transaction_ref TEXT UNIQUE);
CREATE TABLE attendance(attendance_id INT PRIMARY KEY,enrollment_id INT REFERENCES enrollments,class_date DATE,session_no INT,attendance_status TEXT CHECK(attendance_status IN('Present','Absent','Late')));
CREATE TABLE assessments(assessment_id INT PRIMARY KEY,course_id INT REFERENCES courses,assessment_name TEXT,assessment_type TEXT,max_score NUMERIC(6,2),weight_pct NUMERIC(6,2));
CREATE TABLE assessment_submissions(submission_id INT PRIMARY KEY,enrollment_id INT REFERENCES enrollments,assessment_id INT REFERENCES assessments,submitted_at DATE,score NUMERIC(6,2),submission_status TEXT);
CREATE TABLE learning_events(event_id INT PRIMARY KEY,student_id INT REFERENCES students,enrollment_id INT REFERENCES enrollments,event_timestamp TIMESTAMP,event_type TEXT,metadata JSONB);
CREATE TABLE career_sessions(career_session_id INT PRIMARY KEY,student_id INT REFERENCES students,mentor_id INT REFERENCES mentors,session_date DATE,session_type TEXT,session_status TEXT);
CREATE TABLE placement_applications(application_id INT PRIMARY KEY,student_id INT REFERENCES students,course_id INT REFERENCES courses,application_date DATE,company_name TEXT,application_status TEXT);
CREATE TABLE placements(placement_id INT PRIMARY KEY,student_id INT REFERENCES students,application_id INT REFERENCES placement_applications,joining_date DATE,annual_ctc_lpa NUMERIC(8,2),employment_type TEXT);
CREATE TABLE feedback(feedback_id INT PRIMARY KEY,student_id INT REFERENCES students,course_id INT REFERENCES courses,feedback_date DATE,rating INT CHECK(rating BETWEEN 1 AND 5),feedback_category TEXT);
CREATE TABLE support_tickets(ticket_id INT PRIMARY KEY,student_id INT REFERENCES students,created_at TIMESTAMP,resolved_at TIMESTAMP,priority TEXT,ticket_category TEXT,ticket_status TEXT);
CREATE INDEX idx_enrol_student_date ON enrollments(student_id,enrollment_date);
CREATE INDEX idx_enrol_course_status ON enrollments(course_id,enrollment_status);
CREATE INDEX idx_payment_enrol_status ON payments(enrollment_id,payment_status);
CREATE INDEX idx_attendance_enrol_date ON attendance(enrollment_id,class_date);
CREATE INDEX idx_events_student_time ON learning_events(student_id,event_timestamp);
CREATE INDEX idx_events_metadata ON learning_events USING GIN(metadata);
CREATE INDEX idx_open_tickets ON support_tickets(created_at) WHERE ticket_status IN('Open','In Progress');
CREATE TABLE audit.data_quality_log(log_id BIGSERIAL PRIMARY KEY,check_name TEXT,issue_count BIGINT,checked_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,details JSONB);
